import{_ as p,a0 as n,w as a,s as d,I as e,x as i,a1 as t,A as o,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"DevOps 應聘者應該準備回答的 20 個問題 | LCTT x X-CMD","titleTemplate":false,"description":"DevOps 應聘者應該準備回答的 20 個問題 | LCTT (201811) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"DevOps 應聘者應該準備回答的 20 個問題 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"DevOps 應聘者應該準備回答的 20 個問題 | LCTT (201811) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201811/20180308 20 questions DevOps job candidates should be prepared to answer","title":"DevOps 應聘者應該準備回答的 20 個問題","tag":"201811","desc":""},"relativePath":"201811/20180308 20 questions DevOps job candidates should be prepared to answer.md","filePath":"[post].md"}'),u={name:"201811/20180308 20 questions DevOps job candidates should be prepared to answer.md"};function m(f,l,g,T,b,v){const s=n("Link");return a(),d("div",null,[l[29]||(l[29]=e("h1",{id:"devops-應聘者應該準備回答的-20-個問題",tabindex:"-1"},[i("DevOps 應聘者應該準備回答的 20 個問題 "),e("a",{class:"header-anchor",href:"#devops-應聘者應該準備回答的-20-個問題","aria-label":"Permalink to “DevOps 應聘者應該準備回答的 20 個問題”"},"​")],-1)),l[30]||(l[30]=e("blockquote",null,[e("p",null,"想要建立一個積極，富有成效的工作環境？ 在招聘過程中要專注於尋找契合點。")],-1)),l[31]||(l[31]=e("p",null,[e("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/hire-job-career.png?itok=SrZo0QJ3",alt:""})],-1)),e("p",null,[l[1]||(l[1]=i("聘請一個不合適的人",-1)),t(s,{href:"https://www.shrm.org/resourcesandtools/hr-topics/employee-relations/pages/cost-of-bad-hires.aspx"},{default:o(()=>[...l[0]||(l[0]=[i("代價是很高的",-1)])]),_:1}),l[2]||(l[2]=i("。根據 Link 人力資源的首席執行官 Jörgen Sundberg 的統計，招聘、僱傭一名新員工將會花費公司$240,000 之多，當你進行了一次不合適的招聘：",-1))]),l[32]||(l[32]=r("<ul><li>你失去了他們的知識技能。</li><li>你失去了他們的人脈。</li><li>你的團隊將可能進入到一個組織發展的震盪階段</li><li>你的公司將會面臨組織破裂的風險</li></ul><p>當你失去一名員工的時候，你就像丟失了公司版圖中的一塊。同樣值得一提的是另一端的痛苦。應聘到一個錯誤工作崗位的員工會感受到很大的壓力以及整個身心的不滿意，甚至是健康問題。</p><p>另外一方面，當你招聘到合適的人時，新的員工將會：</p><ul><li>豐富公司現有的文化，使你的組織成為一個更好的工作場所。研究表明一個積極的工作文化能夠幫助更長久推動財務業績增長，而且如果你在一個歡快的環境中工作，你更有可能在生活中做的更好。</li><li>熱愛和你的組織在一起工作。當人們熱愛他們所在做的，他們會趨向於做的更好。</li></ul><p>招聘以適合或加強現有的文化在 DevOps 和敏捷團多中是必不可少的。也就是説僱傭到一個能夠鼓勵積極合作的人，以便來自不同背景，有着不同目標和工作方式的團隊能夠在一起有效的工作。你新僱傭的員工應該能夠幫助團隊合作來充分發揮放大他們的價值，同時也能夠增加員工的滿意度以及平衡組織目標的衝突。他或者她應該能夠通過明智的選擇工具和工作流來促進你的組織，文化就是一切。</p>",5)),e("p",null,[l[4]||(l[4]=i("作為我們 2017 年 11 月發佈的一篇文章 ",-1)),t(s,{href:"https://opensource.com/article/17/11/inclusive-workforce-takes-work"},{default:o(()=>[...l[3]||(l[3]=[i("DevOps 的招聘經理應該準備回答的 20 個問題",-1)])]),_:1}),l[5]||(l[5]=i(" 的回應，這篇文章將會重點關注在如何招聘最適合的人。",-1))]),l[33]||(l[33]=r('<h3 id="為什麼招聘走錯了方向" tabindex="-1">為什麼招聘走錯了方向 <a class="header-anchor" href="#為什麼招聘走錯了方向" aria-label="Permalink to “為什麼招聘走錯了方向”">​</a></h3><p>很多公司現在用的典型的僱傭策略是基於人才過剩的基礎上：</p><ul><li>在職位公告欄發佈招聘。</li><li>關注具有所需才能的應聘者。</li><li>儘可能找多的候選者。</li><li>通過面試淘汰弱者。</li><li>通過正式的面試淘汰更多的弱者。</li><li>評估，投票，選擇。</li><li>漸漸接近補償。</li></ul><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/images/life-uploads/hiring_graphic.png?itok=1udGbkhB" alt=""></p><p>職位公告欄是有成千上萬失業者人才過剩的經濟大蕭條時期發明的。在今天的求職市場上已經沒有人才過剩了，然而我們仍然在使用基於此的招聘策略。</p><p><img src="https://opensource.com/sites/default/files/styles/panopoly_image_original/public/images/life-uploads/732px-unemployed_men_queued_outside_a_depression_soup_kitchen_opened_in_chicago_by_al_capone_02-1931_-_nara_-_541927.jpg?itok=HSs4NjCN" alt=""></p><h3 id="僱傭最合適的人員-運用文化和情感" tabindex="-1">僱傭最合適的人員：運用文化和情感 <a class="header-anchor" href="#僱傭最合適的人員-運用文化和情感" aria-label="Permalink to “僱傭最合適的人員：運用文化和情感”">​</a></h3><p>在人才過剩僱傭策略背後的思想是設計工作崗位然後將人員安排進去。</p><p>反而應該反過來：尋找將會積極融入你的商業文化的人才，然後為他們尋找他們熱愛的最合適的崗位。要想實現這樣的目標，你必須能夠圍繞他們熱情為他們創造工作崗位。</p>',9)),e("p",null,[l[8]||(l[8]=e("strong",null,"誰正在尋找一份工作？",-1)),l[9]||(l[9]=i(" 根據一份 2016 年對美國 50000 名開發者的調查顯示，",-1)),t(s,{href:"https://insights.stackoverflow.com/survey/2016#work-job-discovery"},{default:o(()=>[...l[6]||(l[6]=[i("85.7% 的受訪對象",-1)])]),_:1}),l[10]||(l[10]=i("要麼對新的機會不感興趣，要麼對於尋找新工作沒有積極性。在尋找工作的那部分中，有將近 ",-1)),t(s,{href:"https://insights.stackoverflow.com/survey/2016#work-job-discovery"},{default:o(()=>[...l[7]||(l[7]=[i("28.3% 的求職者",-1)])]),_:1}),l[11]||(l[11]=i("來自於朋友的推薦。如果你只是在那些在找工作的人中尋找人才，你將會錯過高端的人才。",-1))]),e("p",null,[l[13]||(l[13]=e("strong",null,"運用團隊力量去發現和尋找潛力的僱員",-1)),l[14]||(l[14]=i("。例如，戴安娜是你的團隊中的一名開發者，她所能提供的機會是，她已經",-1)),t(s,{href:"https://research.hackerrank.com/developer-skills/2018/"},{default:o(()=>[...l[12]||(l[12]=[i("從事編程很多年",-1)])]),_:1}),l[15]||(l[15]=i("而且在期間已經結識了很多從事熱愛他們所從事的工作的人。難道你不認為她所推薦的潛在員工在技能、知識和智慧上要比 HR 所尋找的要優秀嗎？在要求戴安娜分享她同伴之前，通知她即將到來的使命任務，向她闡明你要僱傭潛在有探索精神的團隊，描述在將來會需要的知識領域。",-1))]),l[34]||(l[34]=r('<p><strong>僱員想要什麼？</strong>一份來自千禧年嬰兒潮時期出生的人的對比綜合性研究顯示，20% 的人所想要的是相同的：</p><ol><li>對組織產生積極的影響</li><li>幫助解決社交或者環境上的挑戰</li><li>和一羣有動力的人一起工作</li></ol><h3 id="面試的挑戰" tabindex="-1">面試的挑戰 <a class="header-anchor" href="#面試的挑戰" aria-label="Permalink to “面試的挑戰”">​</a></h3><p>面試應該是招聘者和應聘者雙方為了尋找最合適的人才進行的一次雙方之間的對話。將面試聚焦在企業文化和情感對話兩個問題上：這個應聘者將會豐富你的企業文化並且會熱愛和你在一起工作嗎？你能夠在工作中幫他們取得成功嗎？</p><p><strong>對於招聘經理來説：</strong> 每一次的面試都是你學習如何將自己的組織變得對未來的團隊成員更有吸引力，並且每次積極的面試都可能是你發現人才（即使你不會僱傭）的機會。每個人都將會記得積極有效的面試的經歷。即使他們不會被僱傭，他們將會和他們的朋友談論這次經歷，你會得到一個被推薦的機會。這有很大的好處：如果你無法吸引到這個人才，你也將會從中學習吸取經驗並且改善。</p><p><strong>對面試者來説</strong>：每次的面試都是你釋放激情的機會。</p><h3 id="助你釋放潛在僱員激情的-20-個問題" tabindex="-1">助你釋放潛在僱員激情的 20 個問題 <a class="header-anchor" href="#助你釋放潛在僱員激情的-20-個問題" aria-label="Permalink to “助你釋放潛在僱員激情的 20 個問題”">​</a></h3><ol><li>你熱愛什麼？</li><li>“今天早晨我已經迫不及待的要去工作”，你怎麼看待這句話？</li><li>你曾經最快樂的是什麼？</li><li>你曾經解決問題的最典型的例子是什麼，你是如何解決的？</li><li>你如何看待配對學習？</li><li>你到達辦公室和離開辦公室心裏最先想到的是什麼？</li><li>你如果你有一次改變你之前或者現在的工作中的一件事的機會，將會是什麼事？</li><li>當你在工作的時候，你最樂於去學習什麼？</li><li>你的夢想是什麼，你如何去實現？</li><li>你在學會如何去實現你的追求的時候想要或者需要什麼？</li><li>你的價值觀是什麼？</li><li>你是如何堅守自己的價值觀的？</li><li>在你的生活中平衡意味着什麼？</li><li>你最引以為傲的工作交流能力是什麼？為什麼？</li><li>你最喜歡營造什麼樣的環境？</li><li>你喜歡別人怎樣對待你？</li><li>你信任我們什麼，如何驗證？</li><li>告訴我們你在最近的一個項目中學習到什麼？</li><li>我們還能知道你的其他方面的什麼？</li><li>如果你正在僱傭我，你將會問我什麼問題？</li></ol><hr>',9)),e("p",null,[l[17]||(l[17]=i("via: ",-1)),t(s,{href:"https://opensource.com/article/18/3/questions-devops-employees-should-answer"},{default:o(()=>[...l[16]||(l[16]=[i("https://opensource.com/article/18/3/questions-devops-employees-should-answer",-1)])]),_:1})]),e("p",null,[l[21]||(l[21]=i("作者：",-1)),t(s,{href:"https://opensource.com/users/catherinelouis"},{default:o(()=>[...l[18]||(l[18]=[i("Catherine Louis",-1)])]),_:1}),l[22]||(l[22]=i(" 譯者：",-1)),t(s,{href:"https://github.com/FelixYFZ"},{default:o(()=>[...l[19]||(l[19]=[i("FelixYFZ",-1)])]),_:1}),l[23]||(l[23]=i(" 校對：",-1)),t(s,{href:"https://github.com/wxy"},{default:o(()=>[...l[20]||(l[20]=[i("wxy",-1)])]),_:1})]),e("p",null,[l[26]||(l[26]=i("本文由 ",-1)),t(s,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...l[24]||(l[24]=[i("LCTT",-1)])]),_:1}),l[27]||(l[27]=i(" 原創編譯，",-1)),t(s,{href:"https://linux.cn/"},{default:o(()=>[...l[25]||(l[25]=[i("Linux中國",-1)])]),_:1}),l[28]||(l[28]=i(" 榮譽推出",-1))])])}const C=p(u,[["render",m]]);export{x as __pageData,C as default};
